module top_module(
    input wire [15:0] in,
    input wire SEL,
    input wire A,
    input wire B,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    output wire Y,
    output wire [7:0] OR_output
);// Barrel shifter
