module DebounceCircuit (
	input clk,
	input rst_n,
	input btn_input,
	output reg btn_stable
);
    reg [15:0] counter;
    reg btn_sync;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 0;
            btn_sync <= 0;
            btn_stable <= 0;
        end else begin
            if (btn_input == btn_sync) begin
                if (counter == 16'hFFFF) begin
                    btn_stable <= btn_sync;
                end else begin
                    counter <= counter + 1;
                end
            end else begin
                counter <= 0;
                btn_sync <= btn_input;
            end
        end
    end
endmodule

