        if (SCD == 1'b1) begin
            Q <= 1'b0;
            Q_N <= 1'b1;
        end
        else if (SCE == 1'b1) begin
            Q <= 1'b1;
            Q_N <= 1'b0;
        end
        else if (SET_B == 1'b0) begin
            Q <= 1'b1;
            Q_N <= 1'b0;
        end
        else if (RESET_B == 1'b0) begin
            Q <= 1'b0;
            Q_N <= 1'b1;
        end
        else begin
            Q <= D;
            Q_N <= ~D;
        end
    end

endmodule

