    counter <= counter + 1;
    if (counter == 7) begin
      counter <= 0;
    end

    pwm_counter <= pwm_counter + 1;
    if (pwm_counter == 7) begin
      pwm_counter <= 0;
    end

    case (brightness)
      3'b000: duty_cycle <= 3'b000;
      3'b001: duty_cycle <= pwm_counter < 1 ? 3'b111 : 3'b000;
      3'b010: duty_cycle <= pwm_counter < 2 ? 3'b111 : 3'b000;
      3'b011: duty_cycle <= pwm_counter < 3 ? 3'b111 : 3'b000;
      3'b100: duty_cycle <= pwm_counter < 4 ? 3'b111 : 3'b000;
      3'b101: duty_cycle <= pwm_counter < 5 ? 3'b111 : 3'b000;
      3'b110: duty_cycle <= pwm_counter < 6 ? 3'b111 : 3'b000;
      3'b111: duty_cycle <= 3'b111;
    endcase

    led <= pwm_counter < duty_cycle;
  end

endmodule

