module top_module(
  input clk,
  input rst_in,
  input power_on,
  output reg rst_out
);parameter rst_duration = 10; // number of clock cycles for reset duration

reg [3:0] rst_counter; // 4-bit counter for counting clock cycles
reg rst_state; // state of reset signal

always @(posedge clk) begin
  if (rst_in) begin // asynchronous reset
    rst_counter <= 0;
    rst_state <= 0;
  end
  else if (power_on && !clk) begin // power-on reset
    rst_counter <= 0;
    rst_state <= 1;
  end
  else begin // normal operation
    if (rst_counter < rst_duration) begin
      rst_counter <= rst_counter + 1;
      rst_state <= 1;
    end
    else begin
      rst_counter <= 0;
      rst_state <= 0;
    end
  end
end

assign rst_out = rst_state;

endmodule

