description:
Design a bit shift module that performs various shift operations based on a control signal. The module accepts an n-bit input and uses a 2-bit control input to determine the operation: a left shift when control is 00, a logical right shift when control is 01, and an arithmetic right shift when control is 10. The output is the resulting n-bit value after applying the selected shift operation.
module top_module(
  input [n-1:0] in,
  input [1:0] ctrl,
  output [n-1:0] out
);

code:
module top_module(
  input [n-1:0] in,
  input [1:0] ctrl,
  output [n-1:0] out
);parameter n = 8; // number of input signals

// Left shift operation
assign out = (ctrl == 2'b00) ? (in << 1) : out;

// Right shift operation
assign out = (ctrl == 2'b01) ? (in >> 1) : out;

// Arithmetic right shift operation
assign out = (ctrl == 2'b10) ? ((in[n-1] == 1) ? ({n{1'b1}} & (in >> 1)) : (in >> 1)) : out;

endmodule

module sync_up_counter(
    input clk,
    input sync_reset,
    input enable,
    output reg [3:0] count_out
);

    always @(posedge clk) begin
        if (sync_reset)
            count_out <= 4'b0000;
        else if (enable)
            count_out <= count_out + 1;
    end

endmodule

