module top_module(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);wire c1, c2, c3;

    // First bit
    xor x1(A[0], B[0], c1);
    and a1(A[0], B[0], c2);
    or o1(c1, c2, S[0]);

    // Second bit
    xor x2(A[1], B[1], c1);
    and a2(A[1], B[1], c2);
    and a3(A[0], B[0], c3);
    or o2(c1, c2, c3, S[1]);

    // Third bit
    xor x3(A[2], B[2], c1);
    and a4(A[2], B[2], c2);
    and a5(A[1], B[1], c3);
    or o3(c1, c2, c3, S[2]);

    // Fourth bit
    xor x4(A[3], B[3], c1);
    and a6(A[3], B[3], c2);
    and a7(A[2], B[2], c3);
    or o4(c1, c2, c3, S[3]);

    // Carry-out
    or o5(c1, c2, c3, Cout);

endmodule

module top_module(
    input A1,
    input A2,
    input A3,
    input B1,
    output X
);wire temp1, temp2;

    assign temp1 = (A1) ? A2 : 1'b0;
    assign temp2 = (A1) ? 1'b0 : ((A3) ? B1 : (A2 & B1));

    assign X = temp1 | temp2;

endmodule

