module top_module( 
    input [254:0] in,
    output [7:0] out );reg [7:0] count;
    reg [254:0] shift_reg;
    integer i;

    always @ (in) begin
        shift_reg <= in;
        count <= 8'b0;
        for (i = 0; i < 255; i = i + 1) begin
            if (shift_reg[0] == 1'b1) begin
                count <= count + 1;
            end
            shift_reg <= {shift_reg[253:0], 1'b0};
        end
