module fsm_module (
        input clk,
        input reset,
        input sig,
        output reg out);parameter P0=0, P1=1, P2=2, P3=3;
	reg[1:0] state, next;

	always @(posedge clk)
		if (reset) state <= P0;
		else state <= next;


	always_comb begin
		case (state)
			P0: next = sig ? P1 : P0;
			P1: next = sig ? P2 : P1;
			P2: next = sig ? P3 : P2;
			P3: next = sig ? P0 : P3;
			default: next = 'x;
		endcase
	end

	assign out = (state == P0) || (state == P2);

endmodule

