    if (areset) begin
        shift_reg[0] <= 4'b0;
        shift_reg[1] <= 4'b0;
        shift_reg[2] <= 4'b0;
        shift_amt <= 2'b0;
        q <= 4'b0;
    end else begin
        if (load & ena) begin
            load_data <= data;
        end
        shift_reg[0] <= {shift_reg[0][2:0], shift_reg[1][3]};
        shift_reg[1] <= {shift_reg[1][2:0], shift_reg[2][3]};
        shift_reg[2] <= {shift_reg[2][2:0], load_data[3]};
        case (shift_amt)
            2'b00: q <= shift_reg[0];
