module top_module(dout,
    wr_clk,
    rd_clk,
    I1,
    tmp_ram_rd_en,
    Q,
    O2,
    O1,
    din);output reg [63:0] dout;  // Changed to reg to allow assignment in always block
  output [0:0] Q;
  output [11:0] O1;
  output [11:0] O2;
  input wr_clk;
  input rd_clk;
  input I1;
  input tmp_ram_rd_en;
  input [63:0] din;

  reg [63:0] mem [0:4095];
  reg [11:0] write_ptr = 0;
  reg [11:0] read_ptr = 0;
  reg [11:0] count = 0;
  reg [0:0] full = 0;

  always @(posedge wr_clk) begin
    if (I1 && !full) begin
      mem[write_ptr] <= din;
      write_ptr <= write_ptr + 1;
      count <= count + 1;
      if (write_ptr == 4095) begin  // Corrected the condition to 4095 for valid indexing
        write_ptr <= 0;
      end
      if (count == 4096) begin
        full <= 1;
      end
    end
  end

  always @(posedge rd_clk) begin
    if (tmp_ram_rd_en && !full) begin
      dout <= mem[read_ptr];
      read_ptr <= read_ptr + 1;
      count <= count - 1;
      if (read_ptr == 4095) begin  // Corrected the condition to 4095 for valid indexing
        read_ptr <= 0;
      end
      if (count == 0) begin
        full <= 0;
      end
    end
  end

  assign Q = full;
  assign O1 = count;
  assign O2 = 4096 - count;

endmodule

