description:
Design a clock generator that produces a derived output clock signal (CLK_OUT) based on an input clock signal (CLK_IN) and a reset signal (RST_N). The module features a counter that counts up to a specified maximum value (upper) and toggles the output clock signal whenever the counter reaches a predetermined threshold (nexttick). The counter is initialized to a defined offset value and can be reset asynchronously, ensuring that the output clock starts from a controlled state. This design is useful for creating slower clock signals derived from a faster input clock, facilitating timing control in digital circuits.
module top_module(
  input CLK_IN, // input clock signal
  input RST_N, // reset signal
  output reg CLK_OUT // output clock signal
);

code:
module top_module(
  input CLK_IN, // input clock signal
  input RST_N, // reset signal
  output reg CLK_OUT // output clock signal
);reg [31:0] cntr; // counter
  parameter upper = 100; // maximum value of the counter
  parameter offset = 10; // initial value of the counter
  parameter nexttick = 50; // counter value at which to generate the output clock signal

  always @(posedge CLK_IN or negedge RST_N) begin
    if (!RST_N) begin
      // reset the counter to the initial value
      cntr <= upper - offset;
      CLK_OUT <= 0;
    end else begin
      // increment the counter
      if (cntr < upper) begin
        cntr <= cntr + 1;
      end else begin
        cntr <= 0;
      end

      // generate the output clock signal
      if (cntr == nexttick) begin
        CLK_OUT <= ~CLK_OUT;
      end
    end
  end

endmodule

