module top_module(
    input [3:0] input_data,
    input clk,
    input reset,
    output reg [1:0] output_data
);// Removed the instantiation of unknown modules (sky130_fd_sc_hd__sedfxtp)
    // The following registers will hold intermediate values
    reg [1:0] intermediate_data;

    always @ (posedge clk or posedge reset) begin
        if (reset) begin
            output_data <= 2'b00; // Reset output to '00'
        end else begin
            case (input_data)
                4'd0: intermediate_data <= 2'b00;
                4'd1: intermediate_data <= 2'b00;
                4'd2: intermediate_data <= 2'b00;
                4'd3: intermediate_data <= 2'b00;
                4'd4: intermediate_data <= 2'b00;
                4'd5: intermediate_data <= 2'b01;
                4'd6: intermediate_data <= 2'b01;
                4'd7: intermediate_data <= 2'b01;
                4'd8: intermediate_data <= 2'b01;
                4'd9: intermediate_data <= 2'b01;
                4'd10: intermediate_data <= 2'b01;
