        if (wr && !full_reg) begin
            mem[head] <= din;
            head <= (head == 15) ? 0 : head + 1;
            empty_reg <= 0;
            if (head == tail) begin
                full_reg <= 1;
            end
        end
        if (rd && !empty_reg) begin
            tail <= (tail == 15) ? 0 : tail + 1;
            full_reg <= 0;
            if (tail == head) begin
                empty_reg <= 1;
            end
        end
    end
end

assign empty = empty_reg;
assign full = full_reg;

endmodule

