module top_module(
    input wire wr_en,
    input wire wr_clk,
    input wire rd_clk,
    input wire [7:0] din,
    input wire rst,
    input wire rd_en,
    output reg wr_rst_busy,
    output reg empty,
    output reg full,
    output reg [7:0] dout
  );reg [7:0] mem [15:0];
  reg [3:0] wr_ptr;
  reg [3:0] rd_ptr;
  reg [3:0] count;

  always @(posedge wr_clk) begin
    if (rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
      wr_rst_busy <= 1;
    end else if (wr_en && ~full) begin
      mem[wr_ptr] <= din;
      wr_ptr <= wr_ptr + 1;
      count <= count + 1;
      wr_rst_busy <= 0;
    end else if (wr_en && full) begin
      mem[wr_ptr] <= din;
      wr_ptr <= wr_ptr + 1;
      rd_ptr <= rd_ptr + 1;
      wr_rst_busy <= 0;
    end else if (~wr_en && wr_rst_busy) begin
      wr_rst_busy <= 0;
    end
  end

  always @(posedge rd_clk) begin
    if (rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
      empty <= 1;
      full <= 0;
      dout <= 0;
    end else if (rd_en && ~empty) begin
      dout <= mem[rd_ptr];
      rd_ptr <= rd_ptr + 1;
      count <= count - 1;
      empty <= (count == 1);
      full <= 0;
    end else if (rd_en && empty) begin
      dout <= mem[rd_ptr];
      empty <= 1;
      full <= 0;
    end else if (~rd_en && empty) begin
      empty <= 1;
      full <= 0;
    end else if (count == 16) begin
      full <= 1;
      empty <= 0;
    end
  end

endmodule

